async def modify_webhook(self, webhook_id: str, name: str = None, avatar: str = None) -> _utils.DiscordObject:
    # Assuming we have a method to send a PATCH request to modify the webhook
    payload = {}
    if name is not None:
        payload['name'] = name
    if avatar is not None:
        payload['avatar'] = avatar
    response = await self._http.patch(f'/webhooks/{webhook_id}', json=payload)
    return _utils.DiscordObject.from_dict(response)
